fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    if len <= 1 {
        // If empty or single element, second part is empty.
        (a, Vec::new())
    } else {
        // Split roughly in half
        let mid = len / 2;
        // Use split_at to avoid copies
        let (left_slice, right_slice) = a.split_at(mid);
        // Convert slices to Vecs
        (left_slice.to_vec(), right_slice.to_vec())
    }
}